public class ColorSwatchTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            ColorSwatch crimson = new ColorSwatch("crimson", 220, 20, 60);
            check("toHex", "#DC143C", crimson.toHex());
            check("toString", "ColorSwatch[crimson #DC143C]", crimson.toString());

            ColorSwatch black = new ColorSwatch("ink", 0, 0, 0);
            check("zero channels keep both digits", "#000000", black.toHex());

            ColorSwatch clamped = new ColorSwatch("lime", -5, 300, 0);
            check("channels are clamped", "#00FF00", clamped.toHex());

            check("string concatenation uses toString",
                    "swatch: ColorSwatch[ink #000000]", "swatch: " + black);

            check("summary of two",
                    "ColorSwatch[crimson #DC143C], ColorSwatch[ink #000000]",
                    ColorSwatch.summary(new ColorSwatch[] { crimson, black }));
            check("summary of one", "ColorSwatch[lime #00FF00]",
                    ColorSwatch.summary(new ColorSwatch[] { clamped }));
            check("summary of empty", "(none)", ColorSwatch.summary(new ColorSwatch[0]));
            check("summary of null", "(none)", ColorSwatch.summary(null));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

