public class ColorSwatch {

    private final String name;
    private final int red;
    private final int green;
    private final int blue;

    public ColorSwatch(String name, int red, int green, int blue) {
        this.name = name;
        this.red = clamp(red);
        this.green = clamp(green);
        this.blue = clamp(blue);
    }

    private static int clamp(int value) {
        if (value < 0) {
            return 0;
        }
        if (value > 255) {
            return 255;
        }
        return value;
    }

    public String getName() {
        return name;
    }

    public String toHex() {
        return String.format("#%02X%02X%02X", red, green, blue);
    }

    @Override
    public String toString() {
        return "ColorSwatch[" + name + " " + toHex() + "]";
    }

    public static String summary(ColorSwatch[] swatches) {
        if (swatches == null || swatches.length == 0) {
            return "(none)";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < swatches.length; i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(String.valueOf(swatches[i]));
        }
        return sb.toString();
    }
}
